import{_ as i,a0 as t,w as d,s,ao as l,I as c,x as a,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用Docker Machine部署Swarm集羣 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Docker Machine部署Swarm集羣 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Docker Machine部署Swarm集羣 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Docker Machine部署Swarm集羣 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150625 How to Provision Swarm Clusters using Docker Machine","title":"如何使用Docker Machine部署Swarm集羣","tag":"201508","desc":""},"relativePath":"201508/20150625 How to Provision Swarm Clusters using Docker Machine.md","filePath":"[post].md"}'),m={name:"201508/20150625 How to Provision Swarm Clusters using Docker Machine.md"};function p(h,e,k,w,u,g){const r=t("Link");return d(),s("div",null,[e[13]||(e[13]=l(`<h1 id="如何使用docker-machine部署swarm集羣" tabindex="-1">如何使用Docker Machine部署Swarm集羣 <a class="header-anchor" href="#如何使用docker-machine部署swarm集羣" aria-label="Permalink to “如何使用Docker Machine部署Swarm集羣”">​</a></h1><p>大家好，今天我們來研究一下如何使用Docker Machine部署Swarm集羣。Docker Machine提供了標準的Docker API 支持，所以任何可以與Docker守護進程進行交互的工具都可以使用Swarm來（透明地）擴增到多台主機上。Docker Machine可以用來在個人電腦、雲端以及的數據中心裏創建Docker主機。它為創建服務器，安裝Docker以及根據用户設定來配置Docker客户端提供了便捷化的解決方案。我們可以使用任何驅動來部署swarm集羣，並且swarm集羣將由於使用了TLS加密具有極好的安全性。</p><p>下面是我提供的簡便方法。</p><h3 id="_1-安裝docker-machine" tabindex="-1">1. 安裝Docker Machine <a class="header-anchor" href="#_1-安裝docker-machine" aria-label="Permalink to “1. 安裝Docker Machine”">​</a></h3><p>Docker Machine 在各種Linux系統上都支持的很好。首先，我們需要從Github上下載最新版本的Docker Machine。我們使用curl命令來下載最先版本Docker Machine ie 0.2.0。</p><p>64位操作系統：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p>32位操作系統：</p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下載了最先版本的Docker Machine之後，我們需要對 /usr/local/bin/ 目錄下的docker-machine文件的權限進行修改。命令如下：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>在做完上面的事情以後，我們要確保docker-machine已經安裝正確。怎麼檢查呢？運行<code>docker-machine -v</code>指令，該指令將會給出我們系統上所安裝的docker-machine版本。</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="Installing Docker Machine"></p><p>為了讓Docker命令能夠在我們的機器上運行，必須還要在機器上安裝Docker客户端。命令如下。</p><pre><code># curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
# chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-創建machine" tabindex="-1">2. 創建Machine <a class="header-anchor" href="#_2-創建machine" aria-label="Permalink to “2. 創建Machine”">​</a></h3><p>在將Docker Machine安裝到我們的設備上之後，我們需要使用Docker Machine創建一個machine。在這篇文章中，我們會將其部署在Digital Ocean Platform上。所以我們將使用“digitalocean”作為它的Driver API，然後將docker swarm運行在其中。這個Droplet會被設置為Swarm主控節點，我們還要創建另外一個Droplet，並將其設定為Swarm節點代理。</p><p>創建machine的命令如下：</p><pre><code># docker-machine create --driver digitalocean --digitalocean-access-token &lt;API-Token&gt; linux-dev
</code></pre><p><strong>備註</strong>： 假設我們要創建一個名為“linux-dev”的machine。<code>&lt;API-Token&gt;</code>是用户在Digital Ocean Cloud Platform的Digital Ocean控制面板中生成的密鑰。為了獲取這個密鑰，我們需要登錄我們的Digital Ocean控制面板，然後點擊API選項，之後點擊Generate New Token，起個名字，然後在Read和Write兩個選項上打鈎。之後我們將得到一個很長的十六進制密鑰，這個就是<code>&lt;API-Token&gt;</code>了。用其替換上面那條命令中的API-Token字段。</p><p>現在，運行下面的指令，將Machine 的配置變量加載進shell裏。</p><pre><code># eval &quot;$(docker-machine env linux-dev)&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-digitalocean-cloud.png" alt="Docker Machine Digitalocean Cloud"></p><p>然後，我們使用如下命令將我們的machine標記為ACTIVE狀態。</p><pre><code># docker-machine active linux-dev
</code></pre><p>現在，我們檢查它（指machine）是否被標記為了 ACTIVE &quot;*&quot;。</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-active-list.png" alt="Docker Machine Active List"></p><h3 id="_3-運行swarm-docker鏡像" tabindex="-1">3. 運行Swarm Docker鏡像 <a class="header-anchor" href="#_3-運行swarm-docker鏡像" aria-label="Permalink to “3. 運行Swarm Docker鏡像”">​</a></h3><p>現在，在我們創建完成了machine之後。我們需要將swarm docker鏡像部署上去。這個machine將會運行這個docker鏡像，並且控制Swarm主控節點和從節點。使用下面的指令運行鏡像：</p><pre><code># docker run swarm create
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-create.png" alt="Docker Machine Swarm Create"></p><p>如果你想要在<strong>32位操作系統</strong>上運行swarm docker鏡像。你需要SSH登錄到Droplet當中。</p><pre><code># docker-machine ssh
#docker run swarm create
#exit
</code></pre><h3 id="_4-創建swarm主控節點" tabindex="-1">4. 創建Swarm主控節點 <a class="header-anchor" href="#_4-創建swarm主控節點" aria-label="Permalink to “4. 創建Swarm主控節點”">​</a></h3><p>在我們的swarm image已經運行在machine當中之後，我們將要創建一個Swarm主控節點。使用下面的語句，添加一個主控節點。</p><pre><code># docker-machine create \\
-d digitalocean \\
--digitalocean-access-token &lt;DIGITALOCEAN-TOKEN&gt;
--swarm \\
--swarm-master \\
--swarm-discovery token://&lt;CLUSTER-ID&gt; \\
swarm-master
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-master-create.png" alt="Docker Machine Swarm Master Create"></p><h3 id="_5-創建swarm從節點" tabindex="-1">5. 創建Swarm從節點 <a class="header-anchor" href="#_5-創建swarm從節點" aria-label="Permalink to “5. 創建Swarm從節點”">​</a></h3><p>現在，我們將要創建一個swarm從節點，此節點將與Swarm主控節點相連接。下面的指令將創建一個新的名為swarm-node的droplet，其與Swarm主控節點相連。到此，我們就擁有了一個兩節點的swarm集羣了。</p><pre><code># docker-machine create \\
-d digitalocean \\
--digitalocean-access-token &lt;DIGITALOCEAN-TOKEN&gt;
--swarm \\
--swarm-discovery token://&lt;TOKEN-FROM-ABOVE&gt; \\
swarm-node
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-swarm-nodes.png" alt="Docker Machine Swarm Nodes"></p><h3 id="_6-與swarm主控節點連接" tabindex="-1">6. 與Swarm主控節點連接 <a class="header-anchor" href="#_6-與swarm主控節點連接" aria-label="Permalink to “6. 與Swarm主控節點連接”">​</a></h3><p>現在，我們連接Swarm主控節點以便我們可以依照需求和配置文件在節點間部署Docker容器。運行下列命令將Swarm主控節點的Machine配置文件加載到環境當中。</p><pre><code># eval &quot;$(docker-machine env --swarm swarm-master)&quot;
</code></pre><p>然後，我們就可以跨節點地運行我們所需的容器了。在這裏，我們還要檢查一下是否一切正常。所以，運行<strong>docker info</strong>命令來檢查Swarm集羣的信息。</p><pre><code># docker info
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們可以用Docker Machine輕而易舉地創建Swarm集羣。這種方法有非常高的效率，因為它極大地減少了系統管理員和用户的時間消耗。在這篇文章中，我們以Digital Ocean作為驅動，通過創建一個主控節點和一個從節點成功地部署了集羣。其他類似的驅動還有VirtualBox，Google Cloud Computing，Amazon Web Service，Microsoft Azure等等。這些連接都是通過TLS進行加密的，具有很高的安全性。如果你有任何的疑問，建議，反饋，歡迎在下面的評論框中註明以便我們可以更好地提高文章的質量！</p><hr>`,51)),c("p",null,[e[1]||(e[1]=a("via: ",-1)),o(r,{href:"http://linoxide.com/linux-how-to/provision-swarm-clusters-using-docker-machine/"},{default:n(()=>[...e[0]||(e[0]=[a("http://linoxide.com/linux-how-to/provision-swarm-clusters-using-docker-machine/",-1)])]),_:1})]),c("p",null,[e[5]||(e[5]=a("作者：",-1)),o(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[2]||(e[2]=[a("Arun Pyasi",-1)])]),_:1}),e[6]||(e[6]=a(" 譯者：",-1)),o(r,{href:"https://github.com/DongShuaike"},{default:n(()=>[...e[3]||(e[3]=[a("DongShuaike",-1)])]),_:1}),e[7]||(e[7]=a(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),c("p",null,[e[10]||(e[10]=a("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原創翻譯，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[a("Linux中國",-1)])]),_:1}),e[12]||(e[12]=a(" 榮譽推出",-1))])])}const M=i(m,[["render",p]]);export{x as __pageData,M as default};
